/**
 * Step definitions for the care-bus proof's live website-chat acceptance test.
 *
 * These run inside the playwright-bdd package generated by bdd_playwright_service
 * for https://nonagentic.ai. The generated config bakes that baseURL and uses
 * `missingSteps: fail-on-gen`, so every step below must match the feature exactly.
 *
 * The widget's contract (nonagentic_homepage assets/js/chat-widget.js):
 *   button.cb-fab          opens #cb-panel
 *   #cb-input/#cb-send     enabled only after POST /api/sessions succeeds
 *   .cb-msg.cb-assistant   one bubble per assistant message; .cb-streaming while a
 *                          turn is generating; .cb-bubble holds the text.
 * A turn that produced no text removes its bubble, so "a new settled assistant
 * bubble with text" is the answer.
 */

import { createBdd } from 'playwright-bdd';
import { expect, test } from '@playwright/test';
import { mkdirSync, writeFileSync } from 'node:fs';

const { Given, When, Then } = createBdd();

const slug = (title: string) =>
  title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

// chat-bridge's carebus turn may publish this acknowledgement before the
// platform has composed the answer. It is not the answer.
const PUBLISHED_ACK = 'Thanks, I have everything I need. Checking this for you now.';

let bubblesBefore = 0;
let askedAt = 0;
let answer = '';

Given('I open the website chat', async ({ page }) => {
  await page.goto('/');
  // lang-auto.js inserts a language-suggestion bar from the visitor's IP country.
  // It overlays the page and intercepts the FAB click; a real visitor dismisses
  // it with the same button. The class is stable across translations.
  const dismiss = page.locator('.lang-suggest-x');
  if ((await dismiss.count()) > 0) {
    await dismiss.first().click({ timeout: 3_000 }).catch(() => {});
  }
  await page.locator('button.cb-fab').click();
  // The composer is disabled until the widget has a session; waiting on it is
  // the cheapest proof that the chat backend is reachable from the browser.
  await expect(page.locator('#cb-input')).toBeEnabled({ timeout: 90_000 });
});

When('I ask {string}', async ({ page }, question: string) => {
  bubblesBefore = await page.locator('.cb-msg.cb-assistant').count();
  askedAt = Date.now();
  await page.locator('#cb-input').fill(question);
  // The text the visitor sees the widget holding is the text the platform must
  // receive; assert both ends so a qualifier clarification ("What's your
  // question?") can never be blamed on the harness sending an empty message.
  await expect(page.locator('#cb-input')).toHaveValue(question);
  await page.locator('#cb-send').click();
  await expect(page.locator('.cb-msg.cb-you .cb-bubble').last()).toHaveText(question, {
    timeout: 10_000,
  });
});

Then('I receive a complete answer within {int} seconds', async ({ page }, seconds: number) => {
  const budget = Math.max(1_000, askedAt + seconds * 1000 - Date.now());
  await expect
    .poll(
      async () => {
        const bubbles = page.locator('.cb-msg.cb-assistant');
        const count = await bubbles.count();
        if (count <= bubblesBefore) return '';
        const last = bubbles.nth(count - 1);
        if (await last.evaluate((el) => el.classList.contains('cb-streaming'))) return '';
        const text = (await last.locator('.cb-bubble').innerText()).trim();
        return text === PUBLISHED_ACK ? '' : text;
      },
      { timeout: budget, intervals: [500, 1_000, 2_000, 5_000] },
    )
    .not.toBe('');

  const bubbles = page.locator('.cb-msg.cb-assistant');
  const count = await bubbles.count();
  answer = (await bubbles.nth(count - 1).locator('.cb-bubble').innerText()).trim();
  expect(answer.length).toBeGreaterThan(0);
  const elapsed = Date.now() - askedAt;
  // The runner reads one artifact per scenario after the suite: the text these assertions judged,
  // its title, and the measured latency, kept verbatim as evidence.
  mkdirSync('.proof-answers', { recursive: true });
  writeFileSync(
    `.proof-answers/${slug(test.info().title)}.json`,
    JSON.stringify({
      title: test.info().title,
      title_path: test.info().titlePath,
      answer,
      elapsed_ms: elapsed,
    }),
    'utf8',
  );
  // Evidence that this file's own steps ran (a generated stub would not reach
  // here because the composer never becomes enabled without the Given above).
  test.info().annotations.push({
    type: 'carebus-proof',
    description: `answer ${answer.length} chars in ${elapsed} ms`,
  });
});

Then('the answer has no citation markers', async () => {
  // The shapes the answer stage produces: [1], [1][2], [1, 2]. A prose bracket
  // such as [2026] is not a citation and is allowed by the model.
  expect(answer).not.toMatch(/\[\d{1,3}(?:\s*,\s*\d{1,3})*\]/);
});

Then('the answer has no literal newline escapes', async () => {
  expect(answer).not.toContain('\\n');
  expect(answer).not.toContain('\\r');
});

Then('the answer mentions Care Bus', async () => {
  const normalized = answer.toLowerCase().replace(/-/g, ' ');
  expect(normalized).toContain('care bus');
});

Then('the answer says it cannot answer from the sources', async () => {
  // Grounding: a question outside the knowledge stores must produce a refusal, not a confident
  // unsourced answer. The wording is the model's; the alternatives cover the live and fallback
  // phrasings ("I don't have that in the sources…", "I couldn't find an answer…").
  expect(answer).toMatch(
    /sources|not sure|don't|do not|won't|will not|couldn't|cannot|can't|unable|no information/i,
  );
});
